var placeholders={es:{'Seu nome':'Su nombre','seu@email.com':'su@email.com','seuemail@dominio.com':'sucorreo@dominio.com','Sua senha':'Su contraseña','Escolha sua senha':'Elija su contraseña','DDD e número':'Código de área y número'},en:{'Seu nome':'Your name','seu@email.com':'your@email.com','seuemail@dominio.com':'you@example.com','Sua senha':'Your password','Escolha sua senha':'Choose your password','DDD e número':'Area code and number'}};
function replaceText(node){if(lang==='pt-BR'||!node.nodeValue)return;var k=node.nodeValue.trim(),v=maps[lang][k];if(!v)return;var a=(node.nodeValue.match(/^\s*/)||[''])[0],b=(node.nodeValue.match(/\s*$/)||[''])[0];node.nodeValue=a+v+b}
function apply(root){if(lang==='pt-BR')return;var t=root instanceof Document?root.documentElement:root;if(!t)return;var w=document.createTreeWalker(t,NodeFilter.SHOW_TEXT),n;while(n=w.nextNode()){var p=n.parentElement;if(p&&!/^(SCRIPT|STYLE|NOSCRIPT|TEXTAREA)$/i.test(p.tagName))replaceText(n)}if(t.querySelectorAll)t.querySelectorAll('[placeholder],[aria-label],[title]').forEach(function(el){['placeholder','aria-label','title'].forEach(function(a){var k=el.getAttribute(a);if(!k)return;var v=a==='placeholder'?(placeholders[lang]||{})[k]:maps[lang][k];if(v)el.setAttribute(a,v)})})}
function setLanguage(next){if(valid.indexOf(next)<0)return;try{localStorage.setItem(KEY,next)}catch(e){}location.reload()}
function makeSwitcher(floating){var d=document.createElement('div');d.className='harpia-lang'+(floating?' harpia-lang--floating':'');d.dataset.harpiaLang='1';var x=LANGS[lang];d.innerHTML='<button class="harpia-lang__current" type="button" aria-label="Idioma" aria-expanded="false"><span aria-hidden="true">'+x[0]+'</span><span class="harpia-lang__code">'+x[2]+'</span></button><div class="harpia-lang__menu" hidden>'+valid.map(function(k){var i=LANGS[k];return '<button type="button" data-language="'+k+'"'+(k===lang?' aria-current="true"':'')+'><span aria-hidden="true">'+i[0]+'</span><span>'+i[1]+'</span></button>'}).join('')+'</div>';var b=d.querySelector('.harpia-lang__current'),m=d.querySelector('.harpia-lang__menu');b.addEventListener('click',function(e){e.stopPropagation();m.hidden=!m.hidden;b.setAttribute('aria-expanded',String(!m.hidden))});d.querySelectorAll('[data-language]').forEach(function(q){q.addEventListener('click',function(e){e.preventDefault();setLanguage(q.dataset.language)})});d.addEventListener('click',function(e){e.stopPropagation()});document.addEventListener('click',function(){m.hidden=true;b.setAttribute('aria-expanded','false')},{passive:true});return d}
function host(root){var q=function(s){return root.querySelector?root.querySelector(s):null};return q('.home-header .header-inner')||q('.public-header')||q('.portal-topbar')||q('header .nav')}
function ensure(root){var scope=root instanceof Document?document:root;var current=scope.querySelector?scope.querySelector('[data-harpia-lang="1"]'):null,h=host(scope);if(current&&h&&current.classList.contains('harpia-lang--floating')){current.classList.remove('harpia-lang--floating');h.append(current);return}if(current)return;var d=makeSwitcher(!h);if(h){document.querySelector('.harpia-lang--floating')?.remove();h.append(d)}else if(root instanceof Document)document.body.append(d);else scope.append(d)}
function bind(root){apply(root);ensure(root);apply(root)}
function start(){bind(document);var o=new MutationObserver(function(rs){rs.forEach(function(r){r.addedNodes.forEach(function(n){if(n.nodeType===3)replaceText(n);else if(n.nodeType===1)apply(n)})});if(!document.querySelector('[data-harpia-lang="1"]'))ensure(document)});o.observe(document.body,{childList:true,subtree:true})}
window.HarpiaI18n={language:lang,bindRoot:bind,apply:apply,ensureSwitcher:ensure,setLanguage:setLanguage};
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',start,{once:true}):start();
